export default function WebJourney() {
  const [showAnswer, setShowAnswer] = useState(false);

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <p style={{ color: '#8b949e', marginTop: 0 }}>
        Put these events in order before revealing the answer:
      </p>

      <ol>
        {mixedOrder.map((item) => (
          <li key={item} style={{ marginBottom: 8 }}>{item}</li>
        ))}
      </ol>

      <button onClick={() => setShowAnswer(true)}>
        {showAnswer ? 'Answer Revealed' : 'Reveal Correct Order'}
      </button>

      {showAnswer && (
        <ol style={{ marginTop: 16 }}>
          {correctOrder.map((item) => (
            <li key={item} style={{ marginBottom: 8 }}>{item}</li>
          ))}
        </ol>
      )}
    </div>
  );
}

