export default function ForgeLoopDemo() {
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState(null);
  const scenario = scenarios[index];

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <strong>{scenario.question}</strong>

      <div style={{ display: 'grid', gap: 8, marginTop: 12 }}>
        {scenario.options.map((option, optionIndex) => (
          <button
            key={option}
            onClick={() => setSelected(optionIndex)}
            style={{
              textAlign: 'left',
              padding: 10
            }}
          >
            {option}
          </button>
        ))}
      </div>

      {selected !== null && (
        <div style={{ marginTop: 12, padding: 12 }}>
          <strong>
            {selected === scenario.correct ? 'Good call.' : 'Not quite.'}
          </strong>
          <p>{scenario.explanation}</p>
        </div>
      )}

      <button
        onClick={() => {
          setIndex((value) => (value + 1) % scenarios.length);
          setSelected(null);
        }}
      >
        Next Scenario
