export default function ErrorHandlingLab() {
  const [mode, setMode] = useState('async');
  const [shouldFail, setShouldFail] = useState(true);
  const [message, setMessage] = useState('Ready');

  function parseLesson() {
    const raw = shouldFail
      ? '{ invalid json }'
      : '{ "title": "Error Handling" }';

    return JSON.parse(raw);
  }

  function fetchLesson() {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (shouldFail) {
          reject(new Error('Network request failed'));
          return;
        }

        resolve({ title: 'Error Handling' });
      }, 300);
    });
  }

  async function run() {
    setMessage('Working...');

    if (mode === 'sync') {
      try {
        const lesson = parseLesson();
        setMessage(`Loaded: ${lesson.title}`);
      } catch (error) {
        setMessage(`Could not load lesson: ${error.message}`);
      }
      return;
    }

    try {
      const lesson = await fetchLesson();
      setMessage(`Loaded: ${lesson.title}`);
    } catch (error) {
      setMessage(`Could not load lesson: ${error.message}`);
    }
  }

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <button onClick={() => setMode((value) => value === 'sync' ? 'async' : 'sync')}>
        Mode: {mode}
      </button>
      <button onClick={() => setShouldFail((value) => !value)} style={{ marginLeft: 8 }}>
        Should fail: {String(shouldFail)}
      </button>
      <button onClick={run} style={{ marginLeft: 8 }}>
        Run
      </button>
      <p>{message}</p>
    </div>
  );
}

