export default function CleanupPlayground() {
  const [channel, setChannel] = useState('A');
  const [events, setEvents] = useState([]);
  const [withCleanup, setWithCleanup] = useState(true);

  useEffect(() => {
    function handleMessage(event) {
      setEvents((current) => [
        ...current,
        `Channel ${channel}: ${event.detail}`
      ]);
    }

    window.addEventListener('forge-message', handleMessage);

    if (withCleanup) {
      return () => {
        window.removeEventListener('forge-message', handleMessage);
      };
    }
  }, [channel, withCleanup]);

  function sendMessage() {
    window.dispatchEvent(
      new CustomEvent('forge-message', {
        detail: 'message received'
      })
    );
  }

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <button onClick={() => setChannel((value) => value === 'A' ? 'B' : 'A')}>
        Channel: {channel}
      </button>

      <button
        onClick={() => setWithCleanup((value) => !value)}
        style={{ marginLeft: 8 }}
      >
        Cleanup: {withCleanup ? 'on' : 'off'}
      </button>

      <button onClick={sendMessage} style={{ marginLeft: 8 }}>
        Send external event
      </button>

      <ul>
        {events.map((event, index) => (
          <li key={index}>{event}</li>
        ))}
      </ul>
    </div>
  );
}

