import React from 'react';
import {
  BrowserRouter,
  useSearchParams
} from 'react-router-dom';

const lessons = [
  'Components',
  'Props',
  'State',
  'Composition',
  'Routing'
];

function LessonSearch() {
  const [searchParams, setSearchParams] = useSearchParams();
  const query = searchParams.get('search') ?? '';

  const filtered = lessons.filter((lesson) =>
    lesson.toLowerCase().includes(query.toLowerCase())
  );

  function handleChange(event) {
    const nextQuery = event.target.value;

    setSearchParams((current) => {
      const next = new URLSearchParams(current);

      if (nextQuery) {
        next.set('search', nextQuery);
      } else {
        next.delete('search');
      }

      return next;
    });
  }

  return (
    <main style={{ padding: 16 }}>
      <input
        value={query}
        onChange={handleChange}
        placeholder="Search lessons"
      />

      <p>URL query: {query || '(none)'}</p>

      <ul>
        {filtered.map((lesson) => (
          <li key={lesson}>{lesson}</li>
        ))}
      </ul>
    </main>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <LessonSearch />
    </BrowserRouter>
  );
}

import React, { useEffect, useState } from 'react';
import {
  BrowserRouter,
  useSearchParams
} from 'react-router-dom';

const lessons = [
  'Props',
  'State',
  'Routing',
  'Composition'
];

function SearchPage() {
  const [searchParams] = useSearchParams();
  const urlQuery = searchParams.get('search') ?? '';
  const [query, setQuery] = useState(urlQuery);

  useEffect(() => {
    // This synchronization is a symptom of duplicated state.
    setQuery(urlQuery);
  }, [urlQuery]);

  const filtered = lessons.filter((lesson) =>
    lesson.toLowerCase().includes(query.toLowerCase())
  );

  return (
    <main style={{ padding: 16 }}>
      <p>URL query: {urlQuery}</p>
      <p>Local query: {query}</p>

      <ul>
        {filtered.map((lesson) => (
          <li key={lesson}>{lesson}</li>
        ))}
      </ul>
    </main>
  );
}

export default function App() {
