const cache = new Map();
const MAX_AGE = 60_000;

async function getLesson(lessonId, now, fetchLesson) {
  const cached = cache.get(lessonId);

  if (
    cached &&
    now - cached.timestamp < MAX_AGE
  ) {
    return {
      source: 'cache',
      data: cached.data
    };
  }

  const data = await fetchLesson(lessonId);

  cache.set(lessonId, {
    data,
    timestamp: now
  });

  return {
    source: 'network',
    data
  };
}

