  function submit() {
    setSubmittedQuery(query.trim());
  }

  function clear() {
    setQuery('');
    setSubmittedQuery('');
  }

  return (
    <section>
      <label>
        Search
        <input
          value={query}
          onChange={(event) =>
            setQuery(event.target.value)
          }
        />
      </label>

      <button onClick={submit}>
        Search
      </button>

      <button onClick={clear}>
        Clear
      </button>

      {submittedQuery && (
        <p>
          Searching for: {submittedQuery}
        </p>
      )}
    </section>
  );
}

